"""D03: rebuild offline HTML and independently recomputed records. Python standard library only."""
from pathlib import Path
import json, statistics, hashlib
from collections import defaultdict, Counter

HERE = Path(__file__).resolve().parent
source = json.loads((HERE / 'source.json').read_text(encoding='utf-8-sig'))
tags = source['tags']
records = source['requests']
def med(v): return statistics.median(v) if v else None
def cid(r): return '|'.join(t for t in tags if t in r['tags'])
def summary(rows):
    opened = [r for r in rows if r['closed_day'] is None]
    closed = [r for r in rows if r['closed_day'] is not None]
    return dict(request_count=len(rows), open_count=len(opened), closed_count=len(closed), urgent_open=sum(r['urgent'] for r in opened), work_minutes=sum(r['work_minutes'] for r in rows), open_wait_median=med([source['snapshot_day']-r['created_day'] for r in opened]), closed_duration_median=med([r['closed_day']-r['created_day'] for r in closed]))
groups=defaultdict(list)
for r in records: groups[cid(r)].append(r)
derived = dict(dataset_id='D03', synthetic=True, snapshot_day=source['snapshot_day'], summary=summary(records), combinations=[dict(id=k,tags=k.split('|'),request_ids=[r['request_id'] for r in v],**summary(v)) for k,v in groups.items()], districts={d:summary([r for r in records if r['district']==d]) for d in sorted({r['district'] for r in records})}, requests=[dict(**r,combination_id=cid(r),open_wait_days=source['snapshot_day']-r['created_day'] if r['closed_day'] is None else None,closed_duration_days=r['closed_day']-r['created_day'] if r['closed_day'] is not None else None) for r in records])
# Second algorithm: bit masks and per-id sets independently verify all 32 selections x 3 modes x 8 district subsets.
audits=0
districts=sorted({r['district'] for r in records})
for sm in range(32):
    chosen={t for i,t in enumerate(tags) if sm & (1<<i)}
    for dm in range(8):
        ds={d for i,d in enumerate(districts) if dm & (1<<i)}
        for mode in ('any','all','exact'):
            a={r['request_id'] for r in records if r['district'] in ds and (not chosen or (bool(chosen & set(r['tags'])) if mode=='any' else chosen <= set(r['tags']) if mode=='all' else chosen==set(r['tags'])))}
            b=[]
            for r in records:
                mask=sum(1<<tags.index(t) for t in r['tags'])
                yes=(not sm) or (mask&sm != 0 if mode=='any' else mask&sm==sm if mode=='all' else mask==sm)
                if r['district'] in ds and yes: b.append(r)
            assert a=={r['request_id'] for r in b}
            assert sum(r['work_minutes'] for r in b)==sum(r['work_minutes'] for r in records if r['request_id'] in a)
            assert sum(Counter(cid(r) for r in b).values())==len(a)
            audits+=1
assert len({r['request_id'] for r in records})==len(records)
assert sum(g['request_count'] for g in derived['combinations'])==len(records)
assert sum(g['work_minutes'] for g in derived['combinations'])==derived['summary']['work_minutes']
derived['recomputation']={'selection_states_verified_by_independent_bitmask_algorithm':audits,'unique_ids':True,'exact_combination_conservation':True,'work_conservation':True}
(HERE/'computed.json').write_text(json.dumps(derived,ensure_ascii=False,indent=2),encoding='utf-8', newline='\n')

